const EXP={base:'游戏本体',hos:'石之心',baw:'血与酒'};const state={region:'velen',type:'all',exp:'all',query:'',global:false,branch:false,selected:null,landmarks:true,spoilers:false,revealed:[],choices:{},sim:{snow:true,lodge:true,lab:true,grave:true,visit:false,payment:true,war:'nilfgaard'},baw:{route:'fairy',ribbon:true,diary:true,story:true,fifth:true,forgive:true}};
let DATA,byId,map,tiles,markers,labels,placeNames,highlight,labelFrame;window.atlas={state};
function filtered(){const query=state.query.toLowerCase();return DATA.quests.filter(q=>(state.global||q.region===state.region)&&(state.type==='all'||q.type===state.type)&&(state.exp==='all'||q.expansion===state.exp)&&(!state.branch||q.decisions.length>0||q.id==='q298')&&(!query||[q.title,q.name,q.location,q.trigger,...q.decisions.map(d=>d.title),q.people||''].join(' ').toLowerCase().includes(query))).sort((a,b)=>(a.type==='main'?0:1)-(b.type==='main'?0:1))}
function regionMeta(){return REGIONS.find(r=>r.id===state.region)}
function showMobile(view){document.body.classList.toggle('show-catalog',view==='list');document.body.classList.toggle('show-detail',view==='detail');$('#mobile-map').setAttribute('aria-pressed',String(view==='map'));$('#mobile-list').setAttribute('aria-pressed',String(view==='list'));$('#mobile-detail').setAttribute('aria-pressed',String(view==='detail'));setTimeout(()=>map?.invalidateSize(),50)}
function renderList(){const qs=filtered();$('#total').textContent=DATA.quests.length+' 个任务';$('#list-summary').textContent=`${qs.length} 个任务 · ${qs.filter(q=>q.point).length} 个有地图定位`;$('#quest-list').innerHTML=qs.length?qs.map(q=>`<button class="quest-row ${state.selected===q.id?'selected':''}" data-quest="${esc(q.id)}" aria-pressed="${state.selected===q.id}"><span class="quest-symbol ${q.type}" aria-hidden="true">${q.type==='main'?'◇':'○'}</span><span class="quest-row-text"><strong>${esc(q.title)}</strong><span class="original">${esc(q.name)}</span><span class="row-meta"><span>${q.type==='main'?'主线':'支线'} · ${q.level?'建议等级 '+q.level:'无固定等级'}</span><span class="row-badge">${q.decisions.length?'抉择 '+q.decisions.length:!q.point?'流程触发':q.precision==='landmark'?'地标':''}</span></span></span></button>`).join(''):'<div class="empty">没有符合条件的任务。<br>试试调整筛选，或勾选“跨地区搜索”。</div>';document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>selectQuest(b.dataset.quest));renderMarkers();}
function pinIcon(q,count){return L.divIcon({className:'',html:`<div class="map-pin ${q.type} ${q.precision==='landmark'?'landmark':''} ${state.selected===q.id?'chosen':''}" style="width:25px;height:25px"><span>${count>1?count:q.type==='main'?'!':'·'}</span></div>`,iconSize:[25,25],iconAnchor:[12,12]})}
function renderMarkers(){if(!map)return;markers.clearLayers();const qs=filtered().filter(q=>q.point&&q.region===state.region);const grouped=new Map();for(const q of qs){const key=q.point.latlng.map(n=>n.toFixed(4)).join();if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(q)}for(const group of grouped.values()){const q=group.find(q=>q.id===state.selected)||group[0],m=L.marker(q.point.latlng,{icon:pinIcon(q,group.length),title:group.map(q=>q.title).join('、'),keyboard:true});m.bindTooltip(esc(q.title)+(group.length>1?` 等 ${group.length} 个任务`:''),{direction:'top',offset:[0,-12]});m.on('click',()=>group.length>1?showGroup(group):selectQuest(q.id));m.addTo(markers)}$('#map-count').textContent=`${DATA.quests.filter(q=>q.region===state.region).length} 个任务 · ${qs.length} 个任务已定位`;schedulePlaceNames();}
