const MAJOR_PLACES=new Set(['哀歌桥','尼弗迦德驻军','Hierarch Square','Novigrad Docks','奥森弗特港','乌鸦窝','十字路口旅店','米德考普斯','古老橡树','下瓦伦','七只猫旅馆','Hanged Man\'s Tree','Upper Mill','Brunwich','凯尔卓港','凯尔卓城堡桥','盖迪尼斯','罗弗敦','拉尔维克','Kaer Muire','Svorlag','凯尔莫罕','The Gran\'place','Beauclair Palace','白鸦葡萄园','比武场','普雷格蒙德桥','Belgaard Vineyard']);
function placeName(p){return PLACE_NAMES[p.name]||p.name}
function syncLandmarks(){const b=$('#landmark-toggle');b.setAttribute('aria-pressed',String(state.landmarks));b.textContent=state.landmarks?'地名 ✓':'地名';}
function renderLandmarks(){labels.clearLayers();placeNames.clearLayers();if(!state.landmarks||!regionMeta().code)return;for(const p of DATA.landmarks.filter(p=>p.region===state.region)){L.marker(p.latlng,{pane:'landmarkPoints',title:placeName(p),icon:L.divIcon({className:'road-sign',html:'<span></span>',iconSize:[12,12],iconAnchor:[6,6]})}).bindTooltip(esc(placeName(p)),{direction:'top',className:'place-hover'}).bindPopup(`<strong>${esc(placeName(p))}</strong><p>快速旅行路标</p>${placeName(p)!==p.name?`<small>${esc(p.name)}</small>`:''}`,{className:'place-popup'}).addTo(labels)}schedulePlaceNames();}
function schedulePlaceNames(){if(labelFrame)cancelAnimationFrame(labelFrame);labelFrame=requestAnimationFrame(()=>{labelFrame=null;renderPlaceNames()})}
function renderPlaceNames(){placeNames.clearLayers();if(!state.landmarks||!regionMeta().code||!Number.isFinite(map.getZoom()))return;const size=map.getSize(),mapRect=$('#map').getBoundingClientRect(),fontScale=parseFloat(getComputedStyle(document.documentElement).fontSize)/16,ctx=document.createElement('canvas').getContext('2d'),occupied=[];const overlaps=(a,b)=>a.x<b.x+b.w+4&&a.x+a.w+4>b.x&&a.y<b.y+b.h+4&&a.y+a.h+4>b.y;
 for(const selector of ['.map-heading','.compass','.map-tools','.legend','.attribution']){const b=document.querySelector(selector)?.getBoundingClientRect();if(b&&b.width&&b.height)occupied.push({x:b.x-mapRect.x,y:b.y-mapRect.y,w:b.width,h:b.height})}
 for(const q of filtered().filter(q=>q.point&&q.region===state.region)){const p=map.latLngToContainerPoint(q.point.latlng);occupied.push({x:p.x-14,y:p.y-14,w:28,h:28})}
 const candidates=DATA.landmarks.filter(p=>p.region===state.region).map((p,i)=>({...p,index:i,major:MAJOR_PLACES.has(p.name),point:map.latLngToContainerPoint(p.latlng)})).filter(p=>p.point.x>=8&&p.point.x<=size.x-8&&p.point.y>=8&&p.point.y<=size.y-8).sort((a,b)=>Number(b.major)-Number(a.major)||a.index-b.index);
 for(const p of candidates){const text=placeName(p),font=(p.major?14:13)*fontScale;ctx.font=`${p.major?700:500} ${font}px -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif`;const w=Math.min(Math.ceil(ctx.measureText(text).width+14),Math.max(110,Math.min(230*fontScale,size.x-24))),h=Math.ceil(font*1.45+6),x=p.point.x,y=p.point.y;const positions=(p.major?[9,30,54,82,110]:[9]).flatMap(g=>[{x:x+g,y:y-h/2,g},{x:x-w-g,y:y-h/2,g},{x:x-w/2,y:y+g,g},{x:x-w/2,y:y-h-g,g}]);const box=positions.find(b=>b.x>=6&&b.y>=6&&b.x+w<=size.x-6&&b.y+h<=size.y-6&&!occupied.some(o=>overlaps({...b,w,h},o)));if(!box)continue;occupied.push({...box,w,h});if(box.g>9){const end={x:Math.max(box.x,Math.min(x,box.x+w)),y:Math.max(box.y,Math.min(y,box.y+h))};L.polyline([p.latlng,map.containerPointToLatLng(end)],{pane:'placeNames',color:'#d9c391',opacity:.75,weight:1,interactive:false}).addTo(placeNames)}L.marker(p.latlng,{pane:'placeNames',interactive:false,keyboard:false,icon:L.divIcon({className:'place-label'+(p.major?' major':''),html:`<span title="${esc(text)}">${esc(text)}</span>`,iconSize:[w,h],iconAnchor:[x-box.x,y-box.y]})}).addTo(placeNames)}
}
function setRegion(id){if(!REGIONS.some(r=>r.id===id))return;state.region=id;document.querySelector('.map-shell').classList.toggle('vizima',id==='vizima');if(highlight){highlight.remove();highlight=null}$('#regions').innerHTML=REGIONS.map(r=>`<button data-region="${r.id}" class="${r.id===id?'active':''}" aria-pressed="${r.id===id}">${r.name}</button>`).join('');document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{closeDetail();setRegion(b.dataset.region);showMobile('map')});const r=regionMeta();$('#map-title').textContent=r.title;$('#map-subtitle').textContent=r.en;if(tiles){tiles.remove();tiles=null}labels.clearLayers();if(r.code){tiles=L.tileLayer(`assets/tiles/${r.code}/{z}/{x}/{y}.png`,{minZoom:1,maxZoom:r.max+2,maxNativeZoom:r.max,noWrap:true,bounds:r.code==='WO'?[[-77.6929,-180],[76.5985,180]]:[[-85.0511,-180],[85.0511,180]],errorTileUrl:'assets/tile-empty.svg'}).addTo(map);$('#map-notice').textContent='';renderLandmarks();}else $('#map-notice').textContent='维吉玛王宫是独立室内场景。此处展示流程任务，不使用其他地区地图代替。';map.setView(r.center,r.zoom);renderList();}
function selectQuest(id,focus=true){const q=byId[id];if(!q)return;state.selected=id;if(q.region!==state.region)setRegion(q.region);if(state.type!=='all'&&state.type!==q.type){state.type='all';syncType()}if(state.branch&&!q.decisions.length){state.branch=false;$('#branch-only').checked=false}if(state.exp!=='all'&&state.exp!==q.expansion){state.exp='all';$('#expansion').value='all'}renderList();$('#detail').scrollTop=0;renderDetail();if(state.query&&!filtered().some(a=>a.id===id)){state.query='';$('#search').value='';renderList()}if(q.point&&focus){map.setView(q.point.latlng,Math.max(map.getZoom(),3));if(highlight)highlight.remove();highlight=L.circleMarker(q.point.latlng,{radius:21,weight:1,color:'#f1d8aa',fillOpacity:0,interactive:false}).addTo(map)}else if(highlight){highlight.remove();highlight=null}if(matchMedia('(max-width:700px)').matches)showMobile('detail');}
function linked(ids){return `<div class="linked-quests">${ids.filter(id=>byId[id]).map(id=>`<button data-link="${esc(id)}">${esc(byId[id].title)}</button>`).join('')}</div>`}
function bindLinks(){document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>selectQuest(b.dataset.link));}
function closeDetail(){state.selected=null;$('#detail').hidden=true;if(highlight){highlight.remove();highlight=null}showMobile('map');renderList()}
function detailBase(q,branchHtml){return `<div class="detail-top"><button class="detail-close" id="detail-close" aria-label="关闭任务详情">×</button><div class="detail-kicker">${esc(EXP[q.expansion])} / ${q.type==='main'?'主线任务':'支线任务'}</div><h2>${esc(q.title)}</h2><div class="en-name">${esc(q.name)}</div><div class="chips"><span class="chip">${q.level?'建议等级 '+q.level:'无固定等级'}</span><span class="chip gold">${q.precision==='community'?'社区接取坐标':q.precision==='landmark'?'关联地标定位':q.precision==='unmapped'?'坐标待校准':'流程触发'}</span></div></div><section class="detail-section"><h3>Ⅰ · 从哪里开始</h3><p class="location">${esc(q.location)}</p><p>${esc(q.trigger)}</p>${q.precision==='landmark'?'<p class="fine">空心标记对应地标；NPC 站位和具体入口请对照任务说明。</p>':q.precision==='community'?'<p class="fine">接取点来自社区任务数据，尚未逐点实机复测。</p>':''}${q.cutoff?`<p class="cutoff">进度提醒：${esc(q.cutoff)}</p>`:''}</section><section class="detail-section"><h3>Ⅱ · 前置线索</h3>${q.predecessors.length?linked(q.predecessors)+'<p class="fine">这些是前序任务线索，不代表必须按所列顺序全部完成。条件分支以任务说明为准。</p>':'<p class="fine">本条目没有可解析的前序任务；可能直接探索、自动触发，或有特殊条件。</p>'}</section><section class="detail-section"><h3>Ⅲ · 抉择与影响</h3>${branchHtml}</section><section class="detail-section"><h3>Ⅳ · 对照来源</h3><div class="source-list">${q.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</div><p class="fine">资料核对日期：2026-10-02。${q.reviewed?'本任务关键分支已做文档核对。':'本任务基础条目已纳入目录；分支尚未单独核对。'}</p></section>`}
function hasSpoilers(q){return state.spoilers||state.revealed.includes(q.id)}
function renderDetail(){const q=byId[state.selected];if(!q)return;const previousScroll=$('#detail').scrollTop;$('#detail').hidden=false;let html='<p class="no-branch">尚未收录这项任务的完整分支。请查看攻略；这不表示任务没有选择或后果。</p>';if(!hasSpoilers(q)&&(q.decisions.length||q.id==='q298'))html=`<div class="spoiler-lock"><div class="lock-mark">◈</div><p>${q.decisions.length} 个决策节点。接下来的内容包含人物命运和剧情后果。</p><button class="gold-button" id="reveal">展开本任务剧透</button></div>`;else if(hasSpoilers(q)&&q.decisions.length)html=renderDecisions(q)+(q.id==='q298'?ciriSimulator():q.id==='q416'?bawSimulator():'');$('#detail').innerHTML=detailBase(q,html);$('#detail-close').onclick=closeDetail;$('#reveal')&&($('#reveal').onclick=()=>{if(!state.revealed.includes(q.id))state.revealed.push(q.id);renderDetail()});bindLinks();document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.decision),j=Number(b.dataset.option);state.choices[q.id+':'+i]=j;if(q.id==='q235'&&i===1)delete state.choices[q.id+':2'];if(q.id==='q361'&&i===0)delete state.choices[q.id+':1'];renderDetail()});bindSimulators();$('#detail').scrollTop=previousScroll;}
function nodeAllowed(q,i){if(q.id==='q235'&&i===2)return state.choices['q235:1']===0;if(q.id==='q361'&&i===1)return state.choices['q361:0']===0;return true}
function renderDecisions(q){return q.decisions.map((d,i)=>{const selected=state.choices[q.id+':'+i],o=d.options[selected],allowed=nodeAllowed(q,i);return `<div class="decision"><h4>${esc(d.title)}</h4>${d.note?`<small>${esc(d.note)}</small>`:''}${allowed?`<div class="decision-options">${d.options.map((o,j)=>`<button class="decision-choice" data-decision="${i}" data-option="${j}" aria-pressed="${selected===j}">${esc(o.label)}</button>`).join('')}</div>${o?`<div class="outcome"><span class="outcome-label">这一选择的影响</span><p>${esc(o.effect)}</p>${o.links.length?linked(o.links):''}</div>`:'<p class="fine">选择一个选项，查看它带来的影响。</p>'}`:'<div class="locked-node">先在上一个节点选择调查／觐见路线，再查看这一条件分支。</div>'}<a class="decision-source" href="${esc(d.source.url)}" target="_blank" rel="noopener">${esc(d.source.label)} ↗</a></div>`}).join('')}
function selectHtml(id,label,choices,value,disabled=false){return `<label for="${id}"><span>${label}</span><select id="${id}" ${disabled?'disabled':''}>${choices.map(([v,n])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${n}</option>`).join('')}</select></label>`}
function ciriSimulator(){const sim=state.sim;return `<div class="simulator" id="ciri-simulator"><h4>将这些抉择组合起来</h4><p class="fine">演算不读取存档。先填入你的选择，查看它们共同指向的结果。</p>${selectHtml('sim-snow','安慰希里',[['true','打雪仗（积极）'],['false','一起喝酒（消极）']],sim.snow)}${selectHtml('sim-lodge','女术士集会',[['true','让她独自去'],['false','陪她一起去']],sim.lodge)}${selectHtml('sim-lab','实验室冲突',[['true','支持她发泄'],['false','让她冷静']],sim.lab)}${selectHtml('sim-grave','史凯裘的坟墓',[['true','陪她祭拜'],['false','说没有时间']],sim.grave)}${selectHtml('sim-visit','是否见恩希尔',[['false','不见，直接去威伦'],['true','带她去见恩希尔']],sim.visit)}${selectHtml('sim-payment','恩希尔的酬金',[['true','拒绝酬金'],['false','收下酬金']],sim.payment,!sim.visit)}${selectHtml('sim-war','战争结果',[['nilfgaard','保护罗契，尼弗迦德胜'],['dijkstra','迪科斯彻胜'],['radovid','拉多维德胜']],sim.war)}<div class="sim-result" id="ciri-result" aria-live="polite"></div><p class="fine">${esc(DATA.meta.ciriRuleNote)}</p><a class="decision-source" href="https://witcher.fandom.com/wiki/Something_Ends%2C_Something_Begins_(quest)" target="_blank" rel="noopener">结局规则依据 ↗</a></div>`}
function bawSimulator(){return `<div class="simulator" id="baw-simulator"><h4>姐妹结局的条件链</h4><p class="fine">演算展示两姐妹的最终命运；狄拉夫是否获准离开只在无缎带路线另行选择。</p>${selectHtml('baw-route','最终锁定路线',[['fairy','童话世界'],['elder','暗影长者']],state.baw.route)}${[['ribbon','取得魔法缎带'],['diary','读过儿童房前两条日记'],['story','听完席安娜的故事'],['fifth','调查并问及第五名受害者'],['forgive','在牢房中正确劝她宽恕']].map(([key,label])=>`<label class="check-row" for="baw-${key}"><span>${label}</span><input id="baw-${key}" type="checkbox" ${state.baw[key]?'checked':''} ${state.baw.route==='elder'?'disabled':''}></label>`).join('')}<div id="baw-result" class="sim-result" aria-live="polite"></div><p class="fine">为完整和解路线做文档核对；未逐组合进行游戏实机验证。</p></div>`}
function updateCiriResult(){const r=QuestLogic.ciriEnding(state.sim),name={tragedy:'希里未从白霜归来',empress:'希里成为女皇',witcher:'希里成为狩魔猎人'};$('#ciri-result').innerHTML=`<strong>${name[r.outcome]}</strong>已发生的 ${r.total} 项互动中，${r.positive} 次积极、${r.negative} 次消极。${r.boundary?'<p class="fine">这是二比二边界情形：按 Wiki 的规则推导，尚未实机验证。</p>':''}`}
function updateBawResult(){const r=QuestLogic.bloodWineEnding(state.baw),name={'both-die':'两姐妹均死亡','syanna-dies':'席安娜死亡，安娜存活',reconcile:'两姐妹存活并和解'},why={'elder-lock':'暗影长者路线排除了姐妹和解。','no-ribbon':'缺少缎带，席安娜在泰沙姆穆那被杀。','all-conditions':'童话路线和所有关键前序条件都已满足。','missing-condition':'席安娜暂时获救，但缺少典礼和解所需的条件。'};$('#baw-result').innerHTML=`<strong>${name[r.outcome]}</strong>${why[r.reason]}`}
function bindSimulators(){if($('#ciri-simulator')){updateCiriResult();for(const k of Object.keys(state.sim)){const e=$('#sim-'+k);e.onchange=()=>{state.sim[k]=k==='war'?e.value:e.value==='true';$('#sim-payment').disabled=!state.sim.visit;updateCiriResult()}}}if($('#baw-simulator')){updateBawResult();for(const k of Object.keys(state.baw)){const e=$('#baw-'+k);e.onchange=()=>{state.baw[k]=k==='route'?e.value:e.checked;document.querySelectorAll('#baw-simulator input').forEach(c=>c.disabled=state.baw.route==='elder');updateBawResult()}}}}
function syncType(){document.querySelectorAll('[data-type]').forEach(b=>b.setAttribute('aria-pressed',String(state.type===b.dataset.type)))}
function syncSpoiler(){$('#spoiler').setAttribute('aria-pressed',String(state.spoilers));$('#spoiler').innerHTML=state.spoilers?'◈ 全局剧透展开':'◈ 全局剧透隐藏'}
async function renderAudit(){let qa=null;try{const r=await fetch('validation.json',{cache:'no-store'});if(r.ok)qa=await r.json()}catch{}const exact=DATA.quests.filter(q=>q.precision==='community').length,anchors=DATA.quests.filter(q=>q.precision==='landmark').length;$('#audit-content').innerHTML=`<p class="fine">资料快照 · ${esc(DATA.meta.date)} · ${esc(DATA.meta.scope)}</p><div class="audit-stats"><div class="audit-stat"><strong>${DATA.quests.length}</strong><span>主线／支线目录</span></div><div class="audit-stat"><strong>${exact}+${anchors}</strong><span>社区接取坐标＋关联地标</span></div><div class="audit-stat"><strong>${DATA.meta.reviewedTasks}</strong><span>关键分支文档核对</span></div><div class="audit-stat"><strong>${DATA.meta.decisionNodes}</strong><span>决策节点 · ${DATA.meta.decisionOptions} 个选项</span></div></div><h3>验证结果</h3>${qa?`<div class="audit-table-wrap"><table class="audit-table"><thead><tr><th>验证范围</th><th>实际检查</th><th>结果</th></tr></thead><tbody>${qa.summary.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.detail)}</td><td>${esc(t.status)}</td></tr>`).join('')}</tbody></table></div>`:'<p>自动检查报告尚未生成。地图与分支资料的核对结果如下。</p>'}<p class="fine">检查通过证明资料结构和网页行为符合所列规则，不证明游戏中所有任务在所有版本都能按相同方式触发。</p><h3>关键事实核对</h3><div class="audit-table-wrap"><table class="audit-table"><thead><tr><th>项目</th><th>核对内容</th><th>依据</th></tr></thead><tbody>${DATA.meta.factChecks.map(t=>`<tr><td>${esc(t.claim)}</td><td>${esc(t.result)}</td><td><a href="${esc(t.source)}" target="_blank" rel="noopener">查看来源</a></td></tr>`).join('')}</tbody></table></div><h3>接取点视觉抽样</h3><p>用相同校准方式把接取坐标叠到真实地图上。下列四处与建筑／地标对应；这属于地图一致性检查。</p><div class="review-grid">${[['19','失踪的兄弟 · 洗劫村庄'],['37','扭曲的纵火犯 · 白果园铁匠'],['263','宝剑与饺子 · 诺维格瑞铁匠街区'],['424','唯有一人 · 鲍克兰告示板，非湖上目标']].map(([id,t])=>`<figure><img loading="lazy" src="assets/check-${id}.jpg" alt="${esc(t)}的地图坐标核对"><figcaption>${esc(t)}</figcaption></figure>`).join('')}</div><h3>覆盖与验证边界</h3><ul>${DATA.meta.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>已修正的来源问题</h3><ul>${DATA.meta.corrections.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>资料来源</h3><div class="source-list">${DATA.meta.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`).join('')}</div><div class="audit-downloads"><a href="validation-report.md" download>下载验证报告</a><a href="data.json" download>下载任务数据</a><a href="fact-checks.json" download>下载事实核对清单</a></div><p class="fine">游戏地图与游戏内容版权归 CD PROJEKT RED 所有，地图和坐标来源注明 Witcher3MapViewer。本网站为非官方个人研究工具。Leaflet 1.9.4 使用 BSD-2-Clause 许可。</p>`;}
async function init(){try{const r=await fetch('data.json');if(!r.ok)throw Error('任务资料加载失败');DATA=await r.json();byId=Object.fromEntries(DATA.quests.map(q=>[q.id,q]));map=L.map('map',{zoomControl:false,attributionControl:false,minZoom:1,maxZoom:6,preferCanvas:true,worldCopyJump:false});markers=L.layerGroup().addTo(map);map.createPane('landmarkPoints').style.zIndex=430;map.createPane('placeNames').style.zIndex=440;map.getPane('placeNames').style.pointerEvents='none';labels=L.layerGroup().addTo(map);placeNames=L.layerGroup().addTo(map);map.on('moveend zoomend resize',schedulePlaceNames);window.atlas={state,DATA,filtered,selectQuest,setRegion,map,hasSpoilers,renderDetail,renderList,landmarkLayers:{points:labels,names:placeNames}};registerWebMCP();setRegion(state.region);$('#search').oninput=e=>{state.query=e.target.value;renderList()};$('#expansion').onchange=e=>{state.exp=e.target.value;renderList()};$('#global').onchange=e=>{state.global=e.target.checked;renderList()};$('#branch-only').onchange=e=>{state.branch=e.target.checked;renderList()};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.type=b.dataset.type;syncType();renderList()});$('#spoiler').onclick=()=>{state.spoilers=!state.spoilers;if(!state.spoilers)state.revealed=[];syncSpoiler();renderDetail()};$('#verification').onclick=()=>{$('#audit-dialog').showModal();renderAudit()};$('#close-audit').onclick=()=>$('#audit-dialog').close();$('#audit-dialog').onclick=e=>{if(e.target===$('#audit-dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}};syncLandmarks();$('#landmark-toggle').onclick=()=>{state.landmarks=!state.landmarks;syncLandmarks();renderLandmarks()};$('#reset-map').onclick=()=>{const r=regionMeta();map.setView(r.center,r.zoom)};$('#zoom-in').onclick=()=>map.zoomIn();$('#zoom-out').onclick=()=>map.zoomOut();$('#mobile-map').onclick=()=>showMobile('map');$('#mobile-list').onclick=()=>showMobile('list');$('#mobile-detail').onclick=()=>state.selected?showMobile('detail'):showMobile('list');document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#audit-dialog').open){e.preventDefault();showMobile('list');$('#search').focus()}if(e.key==='Escape'&&!$('#audit-dialog').open&&state.selected)closeDetail()});selectQuest('q67',false);if(matchMedia('(max-width:700px)').matches)showMobile('map')}catch(e){$('#fatal').hidden=false;$('#fatal').textContent='页面资料未能加载。请刷新重试。'+e.message;console.error(e)}}
function showGroup(qs){$('#detail').hidden=false;$('#detail').innerHTML=`<div class="detail-top"><button class="detail-close" id="detail-close" aria-label="关闭任务详情">×</button><div class="detail-kicker">同一地点</div><h2>${qs.length} 个关联任务</h2></div><section class="detail-section"><div class="group-picker">${qs.map(q=>`<button data-link="${esc(q.id)}">${esc(q.title)}<span class="fine"> · ${q.type==='main'?'主线':'支线'}</span></button>`).join('')}</div><p class="fine">同一地标的任务可能在不同剧情阶段触发。</p></section>`;$('#detail-close').onclick=closeDetail;bindLinks();if(matchMedia('(max-width:700px)').matches)showMobile('detail')}
init();

function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool){window.atlas.webMCP='unavailable';return}const lifecycle=new AbortController();const tools=[{name:'search_quests',title:'查找巫师任务',description:'Search the quest catalog by Chinese or English task name, person or place. Does not reveal plot consequences.',inputSchema:{type:'object',properties:{query:{type:'string'},region:{type:'string'},expansion:{type:'string',enum:['all','base','hos','baw']}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('A query under 200 characters is required');if(input.region&&!REGIONS.some(r=>r.id===input.region))throw Error('Unknown region');if(input.expansion&&!['all','base','hos','baw'].includes(input.expansion))throw Error('Unknown expansion');const needle=input.query.toLowerCase();return DATA.quests.filter(q=>(!input.region||input.region===q.region)&&(!input.expansion||input.expansion==='all'||q.expansion===input.expansion)&&[q.title,q.name,q.people||'',q.location].join(' ').toLowerCase().includes(needle)).map(q=>({id:q.id,title:q.title,name:q.name,region:q.region,type:q.type,location:q.location,precision:q.precision})).slice(0,30)}},{name:'open_quest',title:'打开任务详情',description:'Open an existing quest and its map location using the visible interface. Preserves the current spoiler preference.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.id!=='string'||!byId[input.id])throw Error('Unknown quest ID');selectQuest(input.id);return {id:input.id,region:state.region,spoilersVisible:hasSpoilers(byId[input.id])}}}];try{for(const tool of tools)Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(e=>{window.atlas.webMCP='registration-failed';console.warn(e)});window.atlas.webMCP='registered';window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{window.atlas.webMCP='registration-failed'}}
